//! EN-US: Device tests are explicit, local and token-scoped; changing devices never unmutes a call.
//! PT-BR: Testes são explícitos, locais e isolados por token; trocar dispositivos nunca ativa o microfone.
use super::*;
#[derive(Debug)]pub enum AudioMsg{Output,ReloadOutputs,Outputs{request:Uuid,result:anyhow::Result<Vec<Device>>},Test(&'static str),Stop,TestEvent{token:Uuid,event:EngineEvent},Timeout(Uuid),SwitchTimeout(Uuid),Closed}
pub(super) struct Controls{
    pub output:adw::ComboRow,pub level:gtk::LevelBar,pub status:gtk::Label,pub microphone_test:gtk::Button,pub playback_test:gtk::Button,
    pub output_list:Vec<Device>,pub output_device:Option<String>,request:Option<Uuid>,pub pending:Option<(Uuid,&'static str,Option<String>)>,pub(super) test:Option<(Uuid,&'static str,Engine)>,
}
impl Controls{fn stop(&mut self){self.test=None;self.level.set_value(0.0);self.microphone_test.set_label(crate::i18n::tr("Gravar teste (3 s)"));self.playback_test.set_label(crate::i18n::tr("Testar saída de áudio"));self.microphone_test.set_sensitive(true);self.playback_test.set_sensitive(true);}}
pub(super) fn new(microphone:&adw::PreferencesGroup,body:&gtk::Box,sender:&ComponentSender<MainWindowModel>)->Controls{
    let row=adw::ActionRow::new();row.set_title(crate::i18n::tr("Nível do microfone"));let level=gtk::LevelBar::builder().min_value(0.0).max_value(1.0).value(0.0).width_request(120).valign(gtk::Align::Center).build();level.set_widget_name("microphone-level");level.update_property(&[gtk::accessible::Property::Label(crate::i18n::tr("Nível do microfone"))]);row.add_suffix(&level);microphone.add(&row);
    let microphone_test=gtk::Button::with_label(crate::i18n::tr("Gravar teste (3 s)"));let row=adw::ActionRow::new();row.set_title(crate::i18n::tr("Teste do microfone"));row.set_subtitle(crate::i18n::tr("Grava três segundos na memória e reproduz na saída escolhida. Use fones."));microphone_test.set_valign(gtk::Align::Center);row.add_suffix(&microphone_test);microphone.add(&row);
    let output_group=settings::group(body,crate::i18n::tr("Saída de áudio"),crate::i18n::tr("Atualizar saídas de áudio"),sender,||VoiceMsg::Audio(AudioMsg::ReloadOutputs));let output=settings::device_row(crate::i18n::tr("Saída padrão do sistema"));output.set_widget_name("audio-output-device");output_group.add(&output);
    let playback_test=gtk::Button::with_label(crate::i18n::tr("Testar saída de áudio"));playback_test.set_valign(gtk::Align::Center);let row=adw::ActionRow::new();row.set_title(crate::i18n::tr("Teste de reprodução"));row.set_subtitle(crate::i18n::tr("Reproduz um sinal curto na saída escolhida."));row.add_suffix(&playback_test);output_group.add(&row);
    for(button,mode)in [(&microphone_test,"microphone"),(&playback_test,"playback")]{let input=sender.input_sender().clone();button.connect_clicked(move |_|{let _=input.send(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::Test(mode))));});}
    let input=sender.input_sender().clone();output.connect_selected_notify(move |_|{let _=input.send(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::Output)));});
    let status=gtk::Label::new(None);status.set_wrap(true);status.set_xalign(0.0);status.set_widget_name("audio-test-status");body.append(&status);
    Controls{output,level,status,microphone_test,playback_test,output_list:Vec::new(),output_device:None,request:None,pending:None,test:None}
}
impl MainWindowModel{
    pub(super) fn audio_switch(&mut self,kind:&'static str,device:Option<String>,sender:&ComponentSender<Self>){
        if self.voice.audio.pending.is_some(){return;}
        self.voice.audio.stop();
        if self.voice.call.is_none(){if kind=="microphone"{self.voice.device=device;}else{self.voice.audio.output_device=device;}self.voice.audio.status.set_text(crate::i18n::tr("Dispositivo selecionado."));return;}
        let Some(engine)=self.voice.call.as_ref().and_then(|c|c.engine.as_ref())else{self.voice.audio.status.set_text(crate::i18n::tr("Aguarde a conexão antes de trocar o dispositivo."));self.audio_restore_choices();return;};
        let request=Uuid::new_v4();if !engine.send(serde_json::json!({"type":"audio_device","kind":kind,"device":device,"request":request})){self.voice.audio.status.set_text(crate::i18n::tr("Não foi possível solicitar a troca de dispositivo."));self.audio_restore_choices();return;}
        self.voice.audio.pending=Some((request,kind,device));self.voice.audio.status.set_text(crate::i18n::tr("Trocando dispositivo…"));self.voice.devices.set_sensitive(false);self.voice.audio.output.set_sensitive(false);let input=sender.input_sender().clone();gtk::glib::timeout_add_local_once(Duration::from_secs(12),move||{let _=input.send(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::SwitchTimeout(request))));});
    }
    fn audio_restore_choices(&self){let mic=self.voice.device.as_ref().and_then(|id|self.voice.device_list.iter().position(|d|d.id==*id)).map_or(0,|i|i as u32+1);self.voice.devices.set_selected(mic);let out=self.voice.audio.output_device.as_ref().and_then(|id|self.voice.audio.output_list.iter().position(|d|d.id==*id)).map_or(0,|i|i as u32+1);self.voice.audio.output.set_selected(out);self.voice.devices.set_sensitive(true);self.voice.audio.output.set_sensitive(true);}
    pub(super) fn audio_engine(&mut self,event:EngineEvent){match event{
        EngineEvent::AudioLevel{level}=>{self.voice.audio.level.set_value(if level.is_finite(){level.clamp(0.0,1.0)}else{0.0});},
        EngineEvent::AudioDevice{request,kind,success,device}=>{if !self.voice.audio.pending.as_ref().is_some_and(|(id,k,expected)|*id==request&&*k==kind&&*expected==device){return;}self.voice.audio.pending=None;if success{if kind=="microphone"{self.voice.device=device;}else{self.voice.audio.output_device=device;}}self.audio_restore_choices();self.voice.audio.status.set_text(if success{crate::i18n::tr("Dispositivo alterado. O estado do microfone foi mantido.")}else{crate::i18n::tr("A troca falhou. O dispositivo anterior foi restaurado.")});},_=>{}
    }}
    pub(super) fn audio_event(&mut self,msg:AudioMsg,sender:ComponentSender<Self>){match msg{
        AudioMsg::ReloadOutputs=>{let request=Uuid::new_v4();self.voice.audio.request=Some(request);let input=sender.input_sender().clone();self.voice.jobs.push(tokio::spawn(async move{let result=crate::voice::outputs().await;let _=input.send(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::Outputs{request,result})));}));},
        AudioMsg::Outputs{request,result}=>{if self.voice.audio.request!=Some(request){return;}self.voice.audio.request=None;match result{Ok(devices)=>{let previous=self.voice.audio.output_device.clone();let mut labels=vec![crate::i18n::tr("Saída padrão do sistema").to_owned()];labels.extend(devices.iter().map(|d|d.name.clone()));self.voice.audio.output_list=devices;self.voice.audio.output.set_model(Some(&gtk::StringList::new(&labels.iter().map(String::as_str).collect::<Vec<_>>())));let selected=previous.as_ref().and_then(|id|self.voice.audio.output_list.iter().position(|d|d.id==*id)).map_or(0,|i|i as u32+1);self.voice.audio.output.set_selected(selected);if previous.is_some()&&selected==0{self.voice.audio.output_device=None;let message=crate::i18n::tr("A saída de áudio foi desconectada. Escolha outra saída e entre novamente.");self.voice.audio.status.set_text(message);if self.voice.call.is_some(){self.stop_voice(true,message);}}},Err(_)=>self.voice.audio.status.set_text(crate::i18n::tr("Não foi possível listar saídas de áudio."))}},
        AudioMsg::Output=>{let selected=self.voice.audio.output.selected().checked_sub(1).and_then(|i|self.voice.audio.output_list.get(i as usize)).map(|d|d.id.clone());if selected!=self.voice.audio.output_device{self.audio_switch("output",selected,&sender);}},
        AudioMsg::Test(mode)=>{if self.voice.audio.test.is_some(){self.voice.audio.stop();self.voice.audio.status.set_text(crate::i18n::tr("Teste interrompido."));return;}if mode=="microphone"&&self.voice.call.is_some(){self.voice.audio.status.set_text(crate::i18n::tr("Saia da chamada para gravar um teste do microfone."));return;}if self.voice.audio.pending.is_some(){return;}let token=Uuid::new_v4();let input=sender.input_sender().clone();
            #[cfg(test)]let synthetic=self.voice.test_engine;#[cfg(not(test))]let synthetic=false;
            let config=serde_json::json!({"type":"test_start","mode":mode,"device":self.voice.device,"output_device":self.voice.audio.output_device,"microphone_gain":self.voice.gain.value()/100.0,"test_source":synthetic,"test_sink":synthetic});
            let engine=Engine::start(config,move|event|{let _=input.send(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::TestEvent{token,event})));});self.voice.audio.test=Some((token,mode,engine));if mode=="microphone"{self.voice.audio.microphone_test.set_label(crate::i18n::tr("Parar teste"));self.voice.audio.playback_test.set_sensitive(false);}else{self.voice.audio.playback_test.set_label(crate::i18n::tr("Parar teste"));self.voice.audio.microphone_test.set_sensitive(false);}self.voice.audio.status.set_text(crate::i18n::tr("Iniciando teste local…"));let input=sender.input_sender().clone();gtk::glib::timeout_add_local_once(Duration::from_secs(15),move||{let _=input.send(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::Timeout(token))));});
        },
        AudioMsg::TestEvent{token,event}=>{if !self.voice.audio.test.as_ref().is_some_and(|(id,_,_)|*id==token){return;}match event{EngineEvent::AudioLevel{level}=>self.audio_engine(EngineEvent::AudioLevel{level}),EngineEvent::TestState{state}=>match state.as_str(){"recording"=>self.voice.audio.status.set_text(crate::i18n::tr("Gravando três segundos…")),"playback"=>self.voice.audio.status.set_text(crate::i18n::tr("Reproduzindo teste…")),"completed"=>{self.voice.audio.stop();self.voice.audio.status.set_text(crate::i18n::tr("Teste concluído."));},_=>{}},EngineEvent::Error{..}=>{self.voice.audio.stop();self.voice.audio.status.set_text(crate::i18n::tr("O teste falhou. Verifique o dispositivo e as permissões."));},_=>{}}},
        AudioMsg::Timeout(token)=>{if self.voice.audio.test.as_ref().is_some_and(|(id,_,_)|*id==token){self.voice.audio.stop();self.voice.audio.status.set_text(crate::i18n::tr("O teste de áudio demorou demais."));}},
        AudioMsg::SwitchTimeout(request)=>{if self.voice.audio.pending.as_ref().is_some_and(|(id,_,_)|*id==request){self.voice.audio.pending=None;self.audio_restore_choices();self.voice.audio.status.set_text(crate::i18n::tr("A troca não foi confirmada. Entre novamente na chamada."));self.stop_voice(true,crate::i18n::tr("A troca não foi confirmada. Entre novamente na chamada."));}},
        AudioMsg::Stop|AudioMsg::Closed=>{self.voice.audio.stop();},
    }}
}

#[cfg(test)]pub(crate) fn exercise(context:&gtk::glib::MainContext){
    use crate::ui::chat::actions::tests::{mock,pump,until,find_button};
    let(api,backend,server)=tokio::runtime::Handle::current().block_on(mock());let own=tokio::runtime::Handle::current().block_on(api.whoami()).unwrap();let main=MainWindowModel::builder().launch(MainWindowInit{api_client:api,current_user:own}).detach();let window=adw::Window::builder().default_width(1100).default_height(760).content(main.widget()).build();window.present();main.emit(MainWindowMsg::Voice(VoiceMsg::TestEngine));main.emit(MainWindowMsg::Voice(VoiceMsg::Settings));until(context,||main.model().voice.settings.is_visible());let settings=main.model().voice.settings.clone();assert_eq!(main.model().voice.audio.level.value(),0.0);
    find_button(settings.upcast_ref(),"Gravar teste (3 s)").emit_clicked();until(context,||main.model().voice.audio.test.is_some());let stale=main.model().voice.audio.test.as_ref().unwrap().0;
    let wait=|condition:&dyn Fn()->bool|{let end=Instant::now()+Duration::from_secs(15);loop{pump(context);if condition(){break;}assert!(Instant::now()<end,"local synthetic audio test timed out: {}",main.model().voice.audio.status.text());std::thread::sleep(Duration::from_millis(5));}};
    wait(&||main.model().voice.audio.test.is_none());assert_eq!(main.model().voice.audio.status.text(),"Teste concluído.");assert_eq!(main.model().voice.audio.level.value(),0.0);assert!(!backend.lock().unwrap().requests.iter().any(|(_,p,_)|p=="/voice/ice-servers"));
    find_button(settings.upcast_ref(),"Testar saída de áudio").emit_clicked();until(context,||main.model().voice.audio.test.is_some());wait(&||main.model().voice.audio.test.is_none());assert_eq!(main.model().voice.audio.status.text(),"Teste concluído.");
    find_button(settings.upcast_ref(),"Gravar teste (3 s)").emit_clicked();until(context,||main.model().voice.audio.test.is_some());settings.close();until(context,||main.model().voice.audio.test.is_none());main.emit(MainWindowMsg::Voice(VoiceMsg::Audio(AudioMsg::TestEvent{token:stale,event:EngineEvent::AudioLevel{level:1.0}})));pump(context);assert_eq!(main.model().voice.audio.level.value(),0.0);
    let request=Uuid::new_v4();let call=Uuid::new_v4();{let mut model=main.state().get_mut();let voice=&mut model.model.voice;voice.call=Some(Call{id:call,channel:Uuid::new_v4(),connection:Uuid::new_v4(),phase:Phase::Connected,started:Instant::now(),ice:None,engine:None,muted:true});voice.audio.pending=Some((request,"microphone",Some("new-mic".into())));voice.device_list=vec![Device{id:"new-mic".into(),name:"Synthetic microphone".into()}];voice.devices.set_model(Some(&gtk::StringList::new(&["Default","Synthetic microphone"])));}
    main.emit(MainWindowMsg::Voice(VoiceMsg::Engine{call,event:EngineEvent::AudioDevice{request,kind:"microphone".into(),success:true,device:Some("new-mic".into())}}));pump(context);assert_eq!(main.model().voice.device.as_deref(),Some("new-mic"));assert!(main.model().voice.call.as_ref().unwrap().muted);assert!(main.model().voice.call.is_some());
    let request=Uuid::new_v4();{main.state().get_mut().model.voice.audio.pending=Some((request,"output",Some("missing-output".into())));}main.emit(MainWindowMsg::Voice(VoiceMsg::Engine{call,event:EngineEvent::AudioDevice{request,kind:"output".into(),success:false,device:Some("missing-output".into())}}));pump(context);assert!(main.model().voice.audio.output_device.is_none());assert!(main.model().voice.call.as_ref().unwrap().muted);assert!(main.model().voice.audio.status.text().contains("anterior"));
    main.state().get_mut().model.voice.call=None;window.set_content(None::<&gtk::Widget>);window.close();drop(main);server.abort();pump(context);
}
